import math

NEG_INF = float("-inf")


def monotonic_alignment_search(value):
    frames = len(value)
    if frames == 0:
        raise ValueError("no frames to align")
    tokens = len(value[0])
    if frames < tokens:
        raise ValueError(
            f"{frames} frames cannot cover {tokens} tokens without skipping")

    best = [[NEG_INF] * tokens for _ in range(frames)]
    back = [[None] * tokens for _ in range(frames)]
    best[0][0] = value[0][0]
    for t in range(1, frames):
        for s in range(min(t + 1, tokens)):
            stay = best[t - 1][s]
            advance = best[t - 1][s - 1] if s > 0 else NEG_INF
            if advance > stay:
                best[t][s] = value[t][s] + advance
                back[t][s] = "advance"
            else:
                best[t][s] = value[t][s] + stay
                back[t][s] = "stay"

    path = [0] * frames
    s = tokens - 1
    for t in range(frames - 1, -1, -1):
        path[t] = s
        if t > 0 and back[t][s] == "advance":
            s -= 1
    return path


def path_score(value, path):
    return sum(value[t][s] for t, s in enumerate(path))


def durations_from_path(path, n_tokens):
    counts = [0] * n_tokens
    for token in path:
        counts[token] += 1
    return counts


def length_regulate(encodings, durations):
    if len(encodings) != len(durations):
        raise ValueError("one duration per token is required")
    if any(duration < 1 for duration in durations):
        raise ValueError("every token needs at least one frame")
    out = []
    for encoding, duration in zip(encodings, durations):
        out.extend([list(encoding) for _ in range(duration)])
    return out


def reparameterize(mu, log_sigma, eps):
    return [m + math.exp(ls) * e for m, ls, e in zip(mu, log_sigma, eps)]
